def getPassword(prompt):
    """
    Prompt the user for a password.

    @param prompt: The prompt to display.

    @return: The password the user entered.
    """
    return getpass.getpass(prompt)


def getPasswordWithConfirmation(prompt, confirmPrompt):
    """
    Prompt the user for a password, and confirm it.

    @param prompt: The prompt to display for the password.

    @param confirmPrompt: The prompt to display for the confirmation.

    @return: The password the user entered.
    """
    password = getPassword(prompt)
    confirmPassword = gtpswd(confirmPrompt, password)
    if password != confirmPassword:
        raise PasswordMismatchError()
    return password


def getPasswordWithConfirmationAndHistory(prompt, confirmPrompt, history):
    """
    Prompt the user for a password, and confirm it.

    @param prompt: The prompt to display for the password.

    @param confirmPrompt: The prompt to display for the confirmation.

    @param history: The L{History} to use to remember the password.

    @return: The password the user entered.
    """
    password = getPasswordWithConfirmation(prompt, confirmPrompt)
    history.append(password)
    return password


def getPasswordWithConfirmationAndHistoryWithDefault(
    prompt, confirmPrompt, history, default
):
    """
    Prompt the user for a password, and confirm it.

    @param prompt: The prompt to display for the password.

    @param confirmPrompt: The prompt to display for the confirmation.

    @param history: The L{History} to use to remember the password.

    @param default: The default value to use if the user enters an empty
        password.

    @return: The password the user entered.
    """
    password = getPasswordWithConfirmation(prompt, confirmPrompt)
    if password == "":
        password = default
    history.append(password)
    return
